INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Optimierungen ohne Dokumentation nachvollziehbar?', 2, '[{"text": "Nein", "correct": true, "because": "Doku zeigt Verbesserungen"}, {"text": "Ja", "correct": false, "because": "Fehlender Nachweis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Dokumentation von Optimierungen?', 3, '[{"text": "Transparenz", "correct": true, "because": "Zeigt Veränderungen"}, {"text": "UI-Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Hardware", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Optimierungsdokumentation?', 5, '[{"text": "Vorher-Nachher", "correct": true, "because": "Vergleicht Zustände"}, {"text": "Messwerte", "correct": true, "because":ipsychologisches "Zeigt Ergebnisse"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Teamnamen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierungen brauchen Beweise. b) Sie sind nur für Performance.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch Sicherheit etc."}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Dokumentation von Optimierungen?', 4, '[{"text": "Messergebnisse", "correct": false, "because": "Belegt Erfolg"}, {"text": "Grund der Änderung", "correct": false, "because": "Gibt Kontext"}, {"text": "Schriftgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Optimierungen immer gemessen werden müssen?', 2, '[{"text": "Ja", "correct": true, "because": "Beweis der Wirkung"}, {"text": "Nein", "correct": false, "because": "Ohne Messung unklar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format nutze ich für Optimierungsdokumentation?', 3, '[{"text": "Tabellen", "correct": true, "because": "Vergleich übersichtlich"}, {"text": "Freitext", "correct": false, "because": "Weniger strukturiert"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Optimierungsdokumentation effektiv?', 5, '[{"text": "Quantifizierung", "correct": true, "because": "Zeigt Verbesserung"}, {"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}, {"text": "Teamfotos", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Optimierungen sind nur für Code. b) Dokumentation ist optional. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch Systeme, Doku nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Optimierungsdokumentation?', 4, '[{"text": "Vorher-Zustand", "correct": false, "because": "Vergleich nötig"}, {"text": "Messwerte", "correct": false, "because": "Belegt Erfolg"}, {"text": "Design-Details", "correct": true, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Optimierungen ohne Doku sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Nachweis fehlt"}, {"text": "Ja", "correct": false, "because": "Transparenz fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Details sind bei Optimierungen entscheidend?', 4, '[{"text": "Metriken", "correct": true, "because": "Zeigt Fortschritt"}, {"text": "Änderungsgrund", "correct": true, "because": "Erklärt Entscheidung"}, {"text": "Autorname", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Optimierungen nur einmal dokumentiert werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fortlaufende Updates"}, {"text": "Ja", "correct": false, "because": "Änderungen dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Optimierungsdokumentation?', 3, '[{"text": "Messbarkeit", "correct": true, "because": "Belegt Erfolg"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Visuelle Effekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierungen brauchen Vergleichswerte. b) Sie sind nur für Audits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für Teams"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Optimierungsdokumentation?', 5, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Zeigt Entwicklung"}, {"text": "Wissenstransfer", "correct": true, "because": "Team profitiert"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Tests", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Optimierungsdokumentation unwichtig?', 3, '[{"text": "Ergebnisse", "correct": false, "because": "Belegt Erfolg"}, {"text": "Kontext", "correct": false, "because": "Gibt Sinn"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Optimierungen Tests?', 3, '[{"text": "Nein", "correct": true, "because": "Tests validieren"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Optimierungen immer Performance betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Sicherheit etc."}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Optimierungsdokumentation entscheidend?', 4, '[{"text": "Vergleichbarkeit", "correct": true, "because": "Zeigt Fortschritt"}, {"text": "Lange Erklärungen", "correct": false, "because": "Kürze besser"}, {"text": "Teamfotos", "correct": false, "because": "Irrelevant"}]');
